<template>
  <section class="item-page" :class="{ 'drawer-open': drawerVisible }">
    <main class="workspace">
      <header class="page-head"><div><h1>物料管理 <em>{{ total.toLocaleString() }}</em></h1></div><div><el-button size="small" icon="el-icon-upload2" @click="$router.push('/master/imports')">导入物料</el-button><el-button size="small" type="success" icon="el-icon-plus" @click="openCreate">新增物料</el-button></div></header>
      <div class="filter-row">
        <el-input v-model.trim="query.keyword" size="small" clearable prefix-icon="el-icon-search" placeholder="物料编码/名称　请输入物料编码或名称" @keyup.enter.native="search" />
        <el-select v-model="query.item_type" size="small" clearable placeholder="物料类型　请选择"><el-option v-for="type in itemTypes" :key="type.value" :label="type.label" :value="type.value" /></el-select>
        <el-select v-model="query.category_id" size="small" clearable filterable placeholder="分类　请选择"><el-option v-for="row in selectableCategories" :key="row.id" :label="row.full_path" :value="row.id" /></el-select>
        <el-select v-model="query.unit_id" size="small" clearable placeholder="单位　请选择"><el-option v-for="row in businessUnits" :key="row.id" :label="`${row.unit_code} / ${row.unit_name}`" :value="row.id" /></el-select>
        <el-select v-model="query.status" size="small" clearable placeholder="状态　请选择"><el-option label="启用" value="enabled" /><el-option label="停用" value="disabled" /></el-select>
        <span class="spacer" /><el-button size="small" type="success" @click="search">查询</el-button><el-button size="small" @click="reset">重置</el-button>
      </div>
      <section class="table-card">
        <el-table v-loading="loading" :data="rows" border size="mini" :row-class-name="rowClass">
          <el-table-column width="38" align="center"><template slot-scope="{row}"><el-radio v-model="selectedId" :label="row.id"><span /></el-radio></template></el-table-column>
          <el-table-column prop="item_code" label="Item编码" min-width="112" />
          <el-table-column prop="item_name" label="物料名称" min-width="165" show-overflow-tooltip />
          <el-table-column label="类型" min-width="80"><template slot-scope="{row}">{{ itemTypeText(row.item_type) }}</template></el-table-column>
          <el-table-column label="分类" min-width="100"><template slot-scope="{row}">{{ row.category && row.category.category_name || '-' }}</template></el-table-column>
          <el-table-column label="基本单位" min-width="84"><template slot-scope="{row}">{{ canonicalUnitSymbol(row.unit) }}</template></el-table-column>
          <el-table-column label="关联SKU数" width="86" align="center"><template slot-scope="{row}">{{ Number(row.active_sku_relation_count || 0) }}</template></el-table-column>
          <el-table-column label="默认供应商" min-width="140"><template slot-scope="{row}"><span>{{ row.default_supplier && row.default_supplier.supplier_name || '未设置' }}</span></template></el-table-column>
          <el-table-column label="旧数据状态" width="94"><template slot-scope="{row}"><el-tag size="mini" :type="row.data_source === 'legacy' || row.legacy_id ? 'info' : 'success'">{{ legacyStatusText(row) }}</el-tag></template></el-table-column>
          <el-table-column label="状态" width="78"><template slot-scope="{row}"><span class="dot" :class="row.status">{{ statusText(row.status) }}</span></template></el-table-column>
          <el-table-column label="更新时间" min-width="128"><template slot-scope="{row}">{{ formatDate(row.updated_at) }}</template></el-table-column>
          <el-table-column label="操作" width="220" fixed="right"><template slot-scope="{row}"><el-button type="text" size="mini" @click="openDetail(row)">详情</el-button><el-button type="text" size="mini" @click="openEdit(row)">编辑</el-button><el-button type="text" size="mini" :class="row.status==='enabled'?'danger-link':'success-link'" @click="toggleStatus(row)">{{ row.status==='enabled'?'停用':'启用' }}</el-button><el-button v-if="row.status!=='enabled'" type="text" size="mini" class="danger-link" @click="deleteItem(row)">删除</el-button></template></el-table-column>
        </el-table>
        <footer class="pager"><span>共 {{ total.toLocaleString() }} 条</span><el-pagination background small layout="prev, pager, next, sizes" :current-page.sync="query.page" :page-size.sync="query.per_page" :page-sizes="[10,20,50]" :total="total" @current-change="load" @size-change="sizeChange" /></footer>
      </section>
    </main>

    <aside v-if="drawerVisible" class="drawer">
      <header><h2>{{ drawerTitle }}</h2><button @click="closeDrawer"><i class="el-icon-close" /></button></header>

      <div v-if="drawerMode === 'detail'" class="drawer-body detail-body">
        <section class="drawer-card"><h3>基础信息 <i class="el-icon-arrow-up" /></h3><dl><dt>Item编码</dt><dd>{{ selected.item_code }}</dd><dt>物料名称</dt><dd>{{ selected.item_name }}</dd><dt>物料类型</dt><dd>{{ itemTypeText(selected.item_type) }}</dd><dt>分类</dt><dd>{{ categoryPath(selected.category_id) || '-' }}</dd><dt>基本单位</dt><dd>{{ unitLabel(selected.unit) }}</dd><dt>关联SKU数</dt><dd>{{ (selected.sku_relations || []).length }}</dd><dt>状态</dt><dd><span class="dot enabled">{{ statusText(selected.status) }}</span></dd><dt>更新时间</dt><dd>{{ formatDate(selected.updated_at) }}</dd><dt>描述</dt><dd>{{ selected.remark || selected.spec || '-' }}</dd></dl></section>
        <section class="drawer-card"><h3>采购 / 库存属性 <i class="el-icon-arrow-up" /></h3><dl><dt>是否可采购</dt><dd>{{ selected.is_purchase_item?'是':'否' }}</dd><dt>是否库存管理</dt><dd>{{ selected.is_stock_item?'是':'否' }}</dd><dt>安全库存</dt><dd>{{ Number(selected.safety_stock || 0).toFixed(unitPlaces(selected.unit)) }} {{ canonicalUnitSymbol(selected.unit) }}</dd></dl></section>
        <section class="drawer-card"><h3>单件追溯 <i class="el-icon-arrow-up" /></h3><dl><dt>追溯策略</dt><dd>{{ serialTrackingText(selected) }}</dd><dt>系统编号前缀</dt><dd>{{ selected.serial_number_prefix || selected.item_code || '-' }}</dd><dt>入库要求</dt><dd>{{ serialTrackingRequirement(selected) }}</dd></dl></section>
        <section class="drawer-card conversion-card">
          <div class="card-title"><h3>采购单位换算</h3><el-button size="mini" type="success" plain @click="openConversionCreate">新增采购换算</el-button></div>
          <el-table :data="conversions" border size="mini" empty-text="暂无采购单位换算">
            <el-table-column label="采购单位" min-width="72"><template slot-scope="{row}">{{ row.purchase_unit && unitLabel(row.purchase_unit) }}</template></el-table-column>
            <el-table-column label="换算关系" min-width="112"><template slot-scope="{row}">1 {{ row.purchase_unit && row.purchase_unit.symbol }} = {{ number(row.factor) }} {{ row.base_unit && row.base_unit.symbol }}</template></el-table-column>
            <el-table-column label="默认" width="45"><template slot-scope="{row}">{{ row.is_default?'是':'否' }}</template></el-table-column>
            <el-table-column label="实际折算" width="60"><template slot-scope="{row}">{{ row.allow_actual_conversion?'是':'否' }}</template></el-table-column>
            <el-table-column label="状态" width="56"><template slot-scope="{row}"><span :class="['mini-state',row.status]">{{ row.status==='active'?'启用':'停用' }}</span></template></el-table-column>
            <el-table-column label="操作" width="78"><template slot-scope="{row}"><el-button v-if="row.status==='active'" type="text" size="mini" @click="openConversionEdit(row)">编辑</el-button><el-button v-if="row.status==='active'" type="text" size="mini" class="danger-link" @click="disableConversion(row)">停用</el-button></template></el-table-column>
          </el-table>
          <div class="mini-pager"><span>共 {{ conversionTotal }} 条</span><el-pagination small layout="prev, pager, next" :current-page.sync="conversionQuery.page" :page-size="conversionQuery.per_page" :total="conversionTotal" @current-change="loadConversions" /></div>
          <p class="info-line"><i class="el-icon-info" /> 采购换算仅对当前 Item 生效，不影响其他 Item；库存始终以基本单位记账。</p>
        </section>
        <section class="drawer-card"><h3>关联SKU <i class="el-icon-arrow-up" /></h3><el-table :data="selected.sku_relations || []" border size="mini"><el-table-column label="SKU编码"><template slot-scope="{row}">{{ row.sku && row.sku.sku_code }}</template></el-table-column><el-table-column label="SKU名称"><template slot-scope="{row}">{{ row.sku && row.sku.sku_name }}</template></el-table-column></el-table></section>
        <section class="drawer-card"><h3>默认供应商 <i class="el-icon-arrow-up" /></h3><dl><dt>供应商名称</dt><dd>{{ selected.default_supplier && selected.default_supplier.supplier_name || '未设置' }}</dd><dt>供应商编码</dt><dd>{{ selected.default_supplier && selected.default_supplier.supplier_code || '-' }}</dd></dl></section>
        <section class="drawer-card"><h3>旧数据映射 <i class="el-icon-arrow-up" /></h3><dl><dt>数据状态</dt><dd>{{ legacyStatusText(selected) }}</dd><dt>来源系统</dt><dd>{{ selected.legacy_system || '-' }}</dd><dt>来源表</dt><dd>{{ selected.legacy_table || '-' }}</dd><dt>旧记录ID</dt><dd>{{ selected.legacy_id || '-' }}</dd><dt>旧编码</dt><dd>{{ selected.legacy_code || '-' }}</dd></dl></section>
      </div>

      <el-form v-else-if="drawerMode === 'create' || drawerMode === 'edit'" ref="form" :model="form" :rules="rules" label-position="top" size="small" class="drawer-body edit-body">
        <section class="drawer-card"><h3>基础信息 <i class="el-icon-arrow-up" /></h3>
          <el-form-item label="Item编码" prop="item_code"><el-input v-model="form.item_code" disabled /></el-form-item>
          <el-form-item label="物料名称" prop="item_name"><el-input v-model.trim="form.item_name" /></el-form-item>
          <el-form-item label="物料类型" prop="item_type"><el-select v-model="form.item_type" class="full"><el-option v-for="type in itemTypes" :key="type.value" :label="type.label" :value="type.value" /></el-select></el-form-item>
          <el-form-item label="类目" prop="category_id"><el-select v-model="form.category_id" filterable class="full"><el-option v-for="row in selectableCategories" :key="row.id" :label="row.full_path" :value="row.id" /></el-select></el-form-item>
          <el-form-item label="库存基本单位" prop="unit_id" class="base-unit-field"><el-select v-model="form.unit_id" :disabled="!!form.base_unit_locked" class="full"><el-option v-for="row in baseUnitOptions" :key="row.id" :label="unitLabel(row)" :value="row.id" /></el-select><span v-if="chosenBaseUnit" class="precision-label">小数位数：{{ unitPlaces(chosenBaseUnit) }}位</span><p class="blue-note">库存、BOM、采购需求均以此单位记账</p><p v-if="form.base_unit_locked" class="lock-note"><i class="el-icon-lock" /> 已有库存/业务记录，基本单位不可直接修改</p></el-form-item>
        </section>
        <section class="drawer-card"><h3>采购 / 库存属性 <i class="el-icon-arrow-up" /></h3><dl class="bool-list"><dt>是否可采购</dt><dd>{{ form.is_purchase_item?'是':'否' }}</dd><dt>是否库存管理</dt><dd>{{ form.is_stock_item?'是':'否' }}</dd></dl><el-form-item label="属性"><el-checkbox v-model="form.is_purchase_item">可采购</el-checkbox><el-checkbox v-model="form.is_stock_item">库存管理</el-checkbox><el-checkbox v-model="form.is_production_item">生产使用</el-checkbox></el-form-item></section>
        <section class="drawer-card"><h3>单件追溯 <i class="el-icon-arrow-up" /></h3><el-form-item label="追溯策略"><el-select v-model="form.serial_tracking_mode" class="full"><el-option label="仅批次追溯（不录SN）" value="none" /><el-option label="按需逐件编号" value="optional" /><el-option label="必须逐件编号" value="required" /></el-select></el-form-item><el-form-item v-if="form.serial_tracking_mode!=='none'" label="系统编号前缀"><el-input v-model.trim="form.serial_number_prefix" maxlength="30" placeholder="留空时使用Item编码" /><p class="blue-note">到货入库可直接录入供应商SN，也可按合格实际数量由系统生成。</p></el-form-item></section>
        <section v-if="form.id" class="drawer-card"><h3>旧数据映射 <i class="el-icon-arrow-up" /></h3><dl><dt>数据状态</dt><dd>{{ legacyStatusText(form) }}</dd><dt>来源系统</dt><dd>{{ form.legacy_system || '-' }}</dd><dt>来源表</dt><dd>{{ form.legacy_table || '-' }}</dd><dt>旧记录ID</dt><dd>{{ form.legacy_id || '-' }}</dd><dt>旧编码</dt><dd>{{ form.legacy_code || '-' }}</dd></dl></section>
        <el-form-item label="状态"><el-radio-group v-model="form.status"><el-radio label="enabled">启用</el-radio><el-radio label="disabled">停用</el-radio></el-radio-group></el-form-item>
        <el-form-item label="备注"><el-input v-model="form.remark" type="textarea" :rows="3" maxlength="200" show-word-limit /></el-form-item>
      </el-form>

      <el-form v-else ref="conversionForm" :model="conversionForm" :rules="conversionRules" label-position="top" size="small" class="drawer-body conversion-editor">
        <section class="readonly-item"><dl><dt>Item编码</dt><dd>{{ selected.item_code }}</dd><dt>Item名称</dt><dd>{{ selected.item_name }}</dd><dt>库存基本单位</dt><dd>{{ unitLabel(selected.unit) }}</dd></dl></section>
        <el-form-item label="采购单位" prop="purchase_unit_id"><el-select v-model="conversionForm.purchase_unit_id" filterable class="full"><el-option v-for="unit in enabledUnits" :key="unit.id" :label="`${unit.unit_code} ${unit.unit_name}`" :value="unit.id" /></el-select></el-form-item>
        <el-form-item label="换算公式" prop="factor"><div class="formula-row"><el-input value="1" disabled /><span>{{ purchaseUnitSymbol }}</span><b>=</b><el-input-number v-model="conversionForm.factor" :min="0.00000001" :precision="8" :controls="false" @change="setConversionFactor" @blur="captureConversionFactor" /><span>{{ canonicalUnitSymbol(selected.unit) }}</span></div></el-form-item>
        <div class="switch-option"><span>设为默认采购单位</span><el-switch v-model="conversionForm.is_default" active-color="#07883f" /></div>
        <div class="switch-option"><span>允许到货录入实际基本数量</span><el-switch v-model="conversionForm.allow_actual_conversion" active-color="#07883f" /></div>
        <el-form-item label="状态"><el-select value="active" disabled class="full"><el-option label="启用" value="active" /></el-select></el-form-item>
        <div class="date-grid"><el-form-item label="有效期起"><el-date-picker v-model="conversionForm.effective_from" type="datetime" value-format="yyyy-MM-dd HH:mm:ss" class="full" /></el-form-item><el-form-item label="有效期止"><el-date-picker v-model="conversionForm.effective_to" type="datetime" value-format="yyyy-MM-dd HH:mm:ss" class="full" /></el-form-item></div>
        <el-form-item label="变更原因" prop="change_reason"><el-select v-model="conversionForm.change_reason" class="full"><el-option v-for="reason in conversionReasons" :key="reason" :label="reason" :value="reason" /></el-select></el-form-item>
        <el-form-item label="备注"><el-input v-model="conversionForm.remark" type="textarea" :rows="3" maxlength="200" show-word-limit /></el-form-item>
        <section class="check-list"><h4>保存前检查清单</h4><p class="pass">● 采购单位已启用</p><p class="pass">● 基本单位与Item一致</p><p :class="conversionForm.factor>0?'pass':'fail'">● 因子大于0</p><p class="pass">● 无重叠有效关系</p><p class="pass">● 同一Item仅一个默认</p></section>
        <p class="warn-line"><i class="el-icon-warning" /> 换算只对当前 Item 生效；保存新版本后历史单据快照不变</p>
      </el-form>

      <footer><el-button size="small" @click="drawerMode.startsWith('conversion') ? backToDetail() : closeDrawer()">取消</el-button><el-button v-if="drawerMode==='detail'" size="small" @click="openEdit(selected)">编辑物料</el-button><el-button v-if="drawerMode==='detail'" size="small" type="success" @click="$router.push('/master/sku-item-relations')">关联SKU</el-button><el-button v-else size="small" type="success" :loading="saving" @click="drawerMode.startsWith('conversion') ? saveConversion() : saveItem()">{{ drawerMode.startsWith('conversion')?'保存并生效':'保存' }}</el-button></footer>
    </aside>
  </section>
</template>

<script>
import { deleteEntity, disableEntity, disableItemPurchaseConversion, enableEntity, getEntity, getItemCategoryTree, listEntity, listItemPurchaseConversions, saveEntity, saveItemPurchaseConversion } from '../../../api/erp/master'
import { reserveForCreatePage, clearCreatePageReservation } from '../../../utils/documentNumberReservation'

const emptyItem = () => ({ id: null, item_code: '', item_name: '', item_type: 'raw_material', category_id: null, unit_id: null, is_purchase_item: true, is_stock_item: true, is_production_item: false, is_batch_managed: false, is_serial_managed: false, serial_tracking_mode: 'none', serial_number_prefix: '', cost_method: 'weighted_average', default_supplier_id: null, status: 'enabled', remark: '', base_unit_locked: false })
const emptyConversion = () => ({ id: null, purchase_unit_id: null, factor: 1, is_default: false, allow_actual_conversion: false, effective_from: '', effective_to: '', change_reason: '新增采购换算', remark: '' })

export default {
  name: 'ItemList',
  data () { return { loading: false, saving: false, drawerVisible: false, drawerMode: 'detail', reservation: null, rows: [], total: 0, selectedId: null, selected: {}, form: emptyItem(), conversions: [], conversionTotal: 0, conversionQuery: { page: 1, per_page: 5 }, conversionForm: emptyConversion(), categoryTree: [], categories: [], units: [], suppliers: [], query: { keyword: '', item_type: '', category_id: '', unit_id: '', status: '', page: 1, per_page: 20 }, itemTypes: [{ value: 'finished_product', label: '成品' }, { value: 'semi_finished', label: '半成品' }, { value: 'raw_material', label: '原材料' }, { value: 'packaging', label: '包装物' }, { value: 'service', label: '服务' }], conversionReasons: ['新增采购换算', '包装规格调整', '供应方式变更', '主数据修正', '历史数据补全', '其他'], rules: { item_code: [{ required: true, message: '系统未取得Item编码' }], item_name: [{ required: true, message: '请输入物料名称' }], item_type: [{ required: true, message: '请选择物料类型' }], category_id: [{ required: true, message: '请选择末级Item类目' }], unit_id: [{ required: true, message: '请选择库存基本单位' }] }, conversionRules: { purchase_unit_id: [{ required: true, message: '请选择采购单位' }], factor: [{ required: true, message: '请输入大于0的换算因子' }], change_reason: [{ required: true, message: '请选择变更原因' }] } } },
  computed: { drawerTitle () { if (this.drawerMode === 'detail') return this.selected.item_name || '物料详情'; if (this.drawerMode === 'conversion-create') return '新增采购换算'; if (this.drawerMode === 'conversion-edit') return '编辑采购换算'; return this.drawerMode === 'edit' ? '编辑物料' : '新增物料' }, selectableCategories () { return this.categories.filter(row => row.is_leaf && row.status === 'enabled') }, businessUnits () { return this.units.filter(row => !row.is_legacy) }, enabledUnits () { return this.businessUnits.filter(row => row.status === 'enabled') }, currentBaseUnit () { return this.units.find(row => Number(row.id) === Number(this.form.unit_id)) || (this.selected.unit && Number(this.selected.unit.id) === Number(this.form.unit_id) ? this.selected.unit : null) }, baseUnitOptions () { return this.currentBaseUnit && this.currentBaseUnit.is_legacy ? [this.currentBaseUnit, ...this.enabledUnits] : this.enabledUnits }, chosenBaseUnit () { return this.currentBaseUnit }, purchaseUnitSymbol () { const unit = this.units.find(row => Number(row.id) === Number(this.conversionForm.purchase_unit_id)); return unit && (unit.symbol || unit.unit_name) || '采购单位' } },
  created () { this.load(); this.loadOptions() },
  methods: {
    async load () { this.loading = true; try { const { data } = await listEntity('items', this.query); this.rows = data.data || []; this.total = Number(data.total || 0) } catch (e) { this.$message.error(e.userMessage || '物料列表加载失败') } finally { this.loading = false } },
    async loadOptions () { const [categories, units, suppliers] = await Promise.all([getItemCategoryTree(), listEntity('units', { page: 1, per_page: 100, status: 'enabled' }), listEntity('suppliers', { page: 1, per_page: 100, status: 'enabled' })]); this.categoryTree = categories.data.data || []; this.categories = this.flatten(this.categoryTree); this.units = units.data.data || []; this.suppliers = suppliers.data.data || [] },
    flatten (tree) { const rows = []; const visit = list => (list || []).forEach(row => { rows.push(row); visit(row.children) }); visit(tree); return rows },
    search () { this.query.page = 1; this.load() }, reset () { this.query = { keyword: '', item_type: '', category_id: '', unit_id: '', status: '', page: 1, per_page: this.query.per_page }; this.load() }, sizeChange () { this.query.page = 1; this.load() },
    async fetchItem (row) { const { data } = await getEntity('items', row.id); return data },
    async openDetail (row) { this.selectedId = row.id; this.drawerVisible = true; this.drawerMode = 'detail'; try { this.selected = await this.fetchItem(row); this.conversionQuery.page = 1; await this.loadConversions() } catch (e) { this.$message.error(e.userMessage || '物料详情加载失败') } },
    openEdit (row) { this.$router.push(`/master/items/${row.id}/edit`) },
    openCreate () { this.$router.push('/master/items/new') },
    closeDrawer () { this.drawerVisible = false }, async backToDetail () { this.drawerMode = 'detail'; await this.loadConversions() },
    async loadConversions () { if (!this.selected.id) return; const { data } = await listItemPurchaseConversions(this.selected.id, this.conversionQuery); this.conversions = data.data || []; this.conversionTotal = Number(data.total || 0) },
    openConversionCreate () { this.conversionForm = { ...emptyConversion(), is_default: this.conversionTotal === 0 }; this.drawerMode = 'conversion-create' }, openConversionEdit (row) { this.conversionForm = { ...emptyConversion(), ...row, purchase_unit_id: Number(row.purchase_unit_id), factor: Number(row.factor) }; this.drawerMode = 'conversion-edit' },
    setConversionFactor (value) { this.$set(this.conversionForm, 'factor', Number(value || 0)) },
    captureConversionFactor (event) { const value = Number(event && event.target && event.target.value); if (Number.isFinite(value)) this.setConversionFactor(value) },
    saveItem () { this.$refs.form.validate(async valid => { if (!valid) return; this.saving = true; try { const payload = { ...this.form, is_serial_managed: this.form.serial_tracking_mode !== 'none', serial_number_prefix: this.form.serial_tracking_mode === 'none' ? null : (this.form.serial_number_prefix || null) }; if (this.drawerMode === 'create' && this.reservation) Object.assign(payload, { reservation_token: this.reservation.reservation_token, creation_session_id: this.reservation.creation_session_id }); await saveEntity('items', payload); if (this.drawerMode === 'create') clearCreatePageReservation(this.reservation); this.$message.success('物料保存成功'); this.closeDrawer(); await this.load() } catch (e) { this.$message.error(e.userMessage || '物料保存失败') } finally { this.saving = false } }) },
    saveConversion () { this.$refs.conversionForm.validate(async valid => { if (!valid) return; this.saving = true; try { await saveItemPurchaseConversion(this.selected.id, this.conversionForm); await this.backToDetail(); this.$message.success('采购换算已保存并生效') } catch (e) { this.$message.error(e.userMessage || '采购换算保存失败') } finally { this.saving = false } }) },
    async disableConversion (row) { try { const { value } = await this.$prompt('请输入停用原因', '停用采购换算', { inputValidator: value => !!String(value || '').trim() || '停用原因不能为空' }); await disableItemPurchaseConversion(this.selected.id, row.id, { change_reason: value }); this.$message.success('采购换算已停用'); await this.loadConversions() } catch (e) { if (e !== 'cancel' && e !== 'close') this.$message.error(e.userMessage || '停用失败') } },
    async toggleStatus (row) { const enabling = row.status !== 'enabled'; try { await this.$confirm(enabling ? '确认启用该物料？' : '确认停用该物料？', enabling ? '启用确认' : '停用确认'); await (enabling ? enableEntity : disableEntity)('items', row.id); this.$message.success(enabling ? '物料已启用' : '物料已停用'); await this.load() } catch (e) { if (e !== 'cancel') this.$message.error(e.userMessage || '操作失败') } },
    async deleteItem (row) { try { await this.$confirm(`确认删除物料 ${row.item_code} / ${row.item_name}？仅从未被 SKU、采购、库存、BOM 或供应商关系引用的停用物料可以删除。`, '删除物料', { type: 'warning', confirmButtonText: '确认删除' }); await deleteEntity('items', row.id); this.$message.success('物料已删除'); await this.load() } catch (e) { if (e !== 'cancel' && e !== 'close') this.$message.error(e.userMessage || '物料删除失败') } },
    rowClass ({ row }) { return row.id === this.selectedId ? 'selected-row' : '' }, categoryPath (id) { return (this.categories.find(row => Number(row.id) === Number(id)) || {}).full_path || '' }, itemTypeText (value) { return (this.itemTypes.find(type => type.value === value) || {}).label || value || '-' }, serialTrackingMode (row) { return row && (row.serial_tracking_mode || (row.is_serial_managed ? 'required' : 'none')) }, serialTrackingText (row) { return ({ none: '仅批次追溯', optional: '按需逐件编号', required: '必须逐件编号' })[this.serialTrackingMode(row)] || '-' }, serialTrackingRequirement (row) { return this.serialTrackingMode(row) === 'required' ? '合格入库数量必须与唯一SN数量一致' : this.serialTrackingMode(row) === 'optional' ? '本次启用SN时必须逐件完整登记' : '不录SN，按Item/仓库/库位/批次追溯' }, statusText (value) { return value === 'enabled' ? '启用' : '停用' }, legacyStatusText (row) { if (!row) return '非旧数据'; if (row.legacy_id) return '已映射'; if (row.data_source === 'legacy' || row.legacy_system || row.legacy_table || row.legacy_code) return '待治理'; return '非旧数据' }, canonicalUnit (unit) { return unit && (unit.standard_unit || unit.standardUnit || unit) }, canonicalUnitSymbol (unit) { const current = this.canonicalUnit(unit); return current ? `${current.unit_code || ''} ${current.unit_name || ''}`.trim() : '-' }, unitLabel (unit) { const current = this.canonicalUnit(unit); return current ? `${current.unit_code || ''} ${current.unit_name || ''} (${current.symbol || current.unit_name || ''})`.trim() : '-' }, unitPlaces (unit) { const current = this.canonicalUnit(unit); return Number(current && current.decimal_places || 0) }, number (value) { return Number(value || 0).toFixed(6).replace(/0+$/, '').replace(/\.$/, '') }, formatDate (value) { return value ? String(value).replace('T', ' ').slice(0, 16) : '-' }
  }
}
</script>

